// validateStateful at the voted block version: the JVM's spend check, and the block version's source.
//
// ergo-core validates at `stateContext.parameters.blockVersion`, the voted parameter
// (nodeView/state/ErgoStateContext.scala:114; settings/Parameters.scala:80). The activated script version is one
// below it as a signed byte (nodeView/ErgoContext.scala:28). Before it reduces a tree, the interpreter checks the
// tree's version against the activated version (sigma-state 6.0.7 Interpreter.scala:298-331): up to activated
// version 3 a tree above it fails the spend; above activated version 3 a tree above version 3 is accepted
// unverified, at no cost. The storage-rent branch runs first (ergo-core ErgoInterpreter.verify), and a data
// input's script never runs.
//
// Every SANTA entry below is quoted inline from SANTA 8885632. `santaTxInputs` builds the ergots deps from the
// entry object. The transaction is parsed under `blockVersionContext(e.parameters.blockVersion ??
// e.preHeader.version)`, as the runner's transaction arm does.
import { describe, it, expect } from 'vitest'
import { EvalError, ErgoTreeParseError } from '@ergots/ergoscript'
import type { ErgoBox } from '@ergots/ergoscript'
import { validateStateful, computeBoxId } from '../../src/validate/stateful'
import { TxValidationError } from '../../src/errors'
import type { ErgoLikeTransaction, StatefulDeps } from '../../src/index.ts'
import { santaTxInputs, type SantaTxEntry } from './_santa-tx'
import { hexToBytes } from './_load'

type Reject =
  | { check: true }
  | { parse: string }
  | { tx: string }
const CHECK: Reject = { check: true }

function errorOf(fn: () => unknown): unknown {
  try { fn(); } catch (e) { return e }
  return undefined
}

function blockVersionOf(e: SantaTxEntry): number {
  const bv = (e.parameters as { blockVersion?: number }).blockVersion
  return bv !== undefined ? bv : e.preHeader.version
}

function expectReject(e: SantaTxEntry, want: Reject): void {
  const { tx, deps } = santaTxInputs(e)
  const err = errorOf(() => validateStateful(tx, deps))
  if ('check' in want) {
    expect(err).toBeInstanceOf(EvalError)
    expect((err as EvalError).code).toBe('tree-version-above-activated')
    expect((err as Error).message).toMatch(/^ErgoTree version \d+ is higher than activated -?\d+$/)
  } else if ('parse' in want) {
    expect(err).toBeInstanceOf(EvalError)
    expect((err as EvalError).code).toBe(want.parse)
    expect((err as EvalError).cause).toBeInstanceOf(ErgoTreeParseError)
    expect(((err as EvalError).cause as ErgoTreeParseError).code).toBe('tree-version-above-activated')
  } else {
    expect(err).toBeInstanceOf(TxValidationError)
    expect((err as TxValidationError).code).toBe(want.tx)
  }
}

function runFile(label: string, entries: SantaTxEntry[], rejects: Record<string, Reject>): void {
  describe(`SANTA ${label}`, () => {
    for (const e of entries) {
      if (e.expected.valid) {
        it(`${e.name}, block version ${blockVersionOf(e)}: valid, cost ${e.expected.cost}`, () => {
          const { tx, deps } = santaTxInputs(e)
          expect(validateStateful(tx, deps)).toBe(e.expected.cost)
        })
      } else {
        it(`${e.name}, block version ${blockVersionOf(e)}: invalid`, () => {
          expectReject(e, rejects[e.name]!)
        })
      }
    }
  })
}
