const hex = hexToBytes
// A sized SigmaProp(true) `d3` or SigmaProp(false) `d2` tree of the version given.
const sized = (treeVersion: number, prop: 'd3' | 'd2' = 'd3') => `0${(8 + treeVersion).toString(16)}0208${prop}`

/** Build a StatefulDeps.stateContext from one SANTA entry and a block version. */
function stateAt(blockVersion: number): StatefulDeps['stateContext'] {
  const e = EDGES_FILE[0]!
  const { deps } = santaTxInputs(e)
  return { ...deps.stateContext, parameters: { ...e.parameters, blockVersion } }
}

function spend(trees: string[], blockVersion: number): { tx: ErgoLikeTransaction; deps: StatefulDeps } {
  const inputBoxes: ErgoBox[] = trees.map((tree, i) => ({
    value: 1_000_000_000n, ergoTreeBytes: hex(tree), creationHeight: 1, tokens: [], registers: {},
    txId: new Uint8Array(32).fill(i + 1), index: 0,
  }))
  const tx: ErgoLikeTransaction = {
    inputs: inputBoxes.map((b) => ({
      boxId: computeBoxId(b), spendingProof: { proofBytes: new Uint8Array(0), contextExtension: { values: new Map() } },
    })),
    dataInputs: [],
    outputCandidates: [{
      value: 1_000_000_000n * BigInt(trees.length),
      ergoTreeBytes: hex('0008d3'), creationHeight: 1, tokens: [], registers: {},
    }],
  }
  return { tx, deps: { inputBoxes, dataInputBoxes: [], stateContext: stateAt(blockVersion) } }
}
const initCost = (inputs: number) => 10_000 + 2_000 * inputs + 100

describe('an unverified accept ends its own input only (ergo-core ErgoTransaction.scala:453-456: every input is verified)', () => {
  it.each([
    ['a v4 tree, then a v3 SigmaProp(false)', [sized(4), sized(3, 'd2')], 1],
    ['a v3 SigmaProp(false), then a v4 tree', [sized(3, 'd2'), sized(4)], 0],
    ['a v4 SigmaProp(false), then a v3 SigmaProp(false)', [sized(4, 'd2'), sized(3, 'd2')], 1],
  ] as [string, string[], number][])('%s: invalid at the v3 input', (_name, trees, inputIndex) => {
    const { tx, deps } = spend(trees, 5)
    const err = errorOf(() => validateStateful(tx, deps))
    expect(err).toBeInstanceOf(TxValidationError)
    expect((err as TxValidationError).code).toBe('script-reduced-false')
    expect((err as TxValidationError).location?.inputIndex).toBe(inputIndex)
  })

  it.each([
    ['a v4 tree, then a v3 SigmaProp(true)', [sized(4), sized(3)]],
    ['a v3 SigmaProp(true), then a v4 tree', [sized(3), sized(4)]],
    ['a v4 SigmaProp(false), then a v3 SigmaProp(true)', [sized(4, 'd2'), sized(3)]],
  ] as [string, string[]][])('%s: valid at the init cost plus 5 for the v3 input and nothing for the v4 one', (_name, trees) => {
    const { tx, deps } = spend(trees, 5)
    expect(validateStateful(tx, deps)).toBe(initCost(2) + 5)
  })

  it('two v4 inputs: valid at the init cost', () => {
    const { tx, deps } = spend([sized(4), sized(7, 'd2')], 5)
    expect(validateStateful(tx, deps)).toBe(initCost(2))
  })
})

describe('an unverified accept and the cost limit (ergo-core ErgoTransaction.scala:153-159)', () => {
  const limited = (trees: string[], maxBlockCost: number): { tx: ErgoLikeTransaction; deps: StatefulDeps } => {
    const { tx, deps } = spend(trees, 5)
    const parameters = { ...deps.stateContext.parameters, maxBlockCost }
    return { tx, deps: { ...deps, stateContext: { ...deps.stateContext, parameters } } }
  }

  it('a v4 tree under a limit equal to the init cost: valid at exactly that cost', () => {
    const { tx, deps } = limited([sized(4)], initCost(1))
    expect(validateStateful(tx, deps)).toBe(initCost(1))
  })

  it('a v3 SigmaProp(true) under the same limit is over it, and valid with 5 more', () => {
    const at = limited([sized(3)], initCost(1))
    expect((errorOf(() => validateStateful(at.tx, at.deps)) as { code?: string }).code).toBe('cost-limit-exceeded')
    const above = limited([sized(3)], initCost(1) + 5)
    expect(validateStateful(above.tx, above.deps)).toBe(initCost(1) + 5)
  })
})

describe('the voted block version is required', () => {
  const without = (parameters: unknown): StatefulDeps => {
    const { deps } = spend([sized(3)], 4)
    return {
      ...deps,
      stateContext: { ...deps.stateContext, parameters: parameters as StatefulDeps['stateContext']['parameters'] },
    }
  }

  it.each([
    ['no parameters', undefined],
    ['parameters without a block version', { maxBlockCost: 1_000_000 }],
    ['a block version that is not an integer', { blockVersion: 3.5 }],
    ['a block version that is a string', { blockVersion: '4' }],
    ['a block version that is NaN', { blockVersion: NaN }],
  ])('%s: a TypeError', (_name, parameters) => {
    const { tx } = spend([sized(3)], 4)
    expect(() => validateStateful(tx, without(parameters))).toThrow(TypeError)
  })

  it('the TypeError comes before anything is validated', () => {
    const { tx, deps } = spend([sized(3)], 4)
    tx.outputCandidates[0]!.value -= 1n
    expect((errorOf(() => validateStateful(tx, deps)) as TxValidationError).code).toBe('value-not-conserved')
    expect(() => validateStateful(tx, without({}))).toThrow(TypeError)
  })
})

describe('the height rules at a block version beyond a byte read as the JVM reads it', () => {
  // SANTA `rent-tree-v4-dust-accept#6` runs the storage-rent branch before the script path. At block version 200
  // the signed byte is -56 and the monotonic-height rule does not apply (ergo-core ErgoTransaction.scala:383-392).
  const rent = V6_FILE.find((e) => e.name === 'rent-tree-v4-dust-accept#6')!
  it.each([200, 129, 0])('block version %i: the rent spend is valid at its blessed cost', (blockVersion) => {
    const { tx, deps } = santaTxInputs({ ...rent, parameters: { ...rent.parameters, blockVersion } })
    expect(validateStateful(tx, deps)).toBe(rent.expected.cost!)
  })
})
